cmd="${experiments[$SLURM_ARRAY_TASK_ID - 1]}"
mn=$(sed -E 's/.*--model_name="([^"]+)".*/\1/' <<<"$cmd")
exp=$(sed -E 's/.*--experiments_dir="([^"]+)".*/\1/' <<<"$cmd")
if [ -f "$exp/$mn.pt" ] && [ "$(wc -l < "$exp/$mn.csv" 2>/dev/null || echo 0)" -ge 1001 ]; then echo "already done: $mn"; exit 0; fi
sleep $(( (RANDOM % 40) + SLURM_ARRAY_TASK_ID % 15 ))
ok=0
for attempt in 1 2 3 4 5; do
  eval "$cmd" && { ok=1; break; }
  echo "attempt $attempt failed, backoff" >&2
  sleep $(( attempt*45 + RANDOM%30 ))
done
[ "$ok" = "1" ] || { echo "ALL ATTEMPTS FAILED: $mn" >&2; exit 1; }
